  private readonly System.Collections.Generic.List<BridgeLowering> bridgeLowerings=new System.Collections.Generic.List<BridgeLowering>();
  private void BeginBridgeLowering(){var t=chapterFocus==null?null:chapterFocus.transform.Find("Lowered evacuation bridge");if(t==null)return;bridgeLowerings.Add(new BridgeLowering{root=t.gameObject,scale=t.localScale,at=t.position,start=Time.unscaledTime});t.localScale=new Vector3(t.localScale.x*.08f,t.localScale.y,1);t.position+=Vector3.left*1.95f*.92f;}
  private void TickBridgeLowerings(){TickWorkerEvacuation();for(int i=bridgeLowerings.Count-1;i>=0;i--){var b=bridgeLowerings[i];if(b.root==null){bridgeLowerings.RemoveAt(i);continue;}float t=Mathf.Clamp01((Time.unscaledTime-b.start)/.85f);float f=Mathf.Lerp(.08f,1,Mathf.SmoothStep(0,1,t));b.root.transform.localScale=new Vector3(b.scale.x*f,b.scale.y,b.scale.z);b.root.transform.position=b.at+Vector3.left*1.95f*(1-f);if(t>=1)bridgeLowerings.RemoveAt(i);}}
  private readonly System.Collections.Generic.Dictionary<int,Sprite> workshopArt=new System.Collections.Generic.Dictionary<int,Sprite>();
  private Sprite WorkshopProp(int index){Sprite s;if(workshopArt.TryGetValue(index,out s)&&s!=null)return s;var t=Resources.Load<Texture2D>("NakiArt/FireWorkshop/environment");if(t==null)throw new InvalidOperationException("Missing forge environment");t.filterMode=FilterMode.Point;float w=t.width/2f,h=t.height/2f;Rect r=new Rect(index%2*w,(1-index/2)*h,w,h);if(index==0)r=new Rect(t.width*120f/1536,t.height*(1024-507f)/1024,t.width*568f/1536,t.height*498f/1024);if(index==3)r=new Rect(t.width*815f/1536,t.height*(1024-1013f)/1024,t.width*620f/1536,t.height*490f/1024);s=Sprite.Create(t,r,index==0||index==3?Vector2.one*.5f:new Vector2(.5f,.12f),r.height/(index==0?3.2f:index==3?1.2f:1.5f),0,SpriteMeshType.FullRect);ownedAssets.Add(s);workshopArt[index]=s;return s;}
  private void LoadWorkshopArt(){var t=Resources.Load<Texture2D>("NakiArt/FireWorkshop/creatures");if(t==null)throw new InvalidOperationException("Missing forge creatures");t.filterMode=FilterMode.Point;EnemyKind[] kinds={EnemyKind.ForgeMaster,EnemyKind.FurnaceCore,EnemyKind.ForgeGuard,EnemyKind.MoltenCrab};Rect[] regions={new Rect(40,40,675,600),new Rect(720,150,490,500),new Rect(35,650,560,550),new Rect(600,755,650,450)};for(int i=0;i<4;i++){Rect r=regions[i];r=new Rect(r.x*t.width/1254,(1254-r.yMax)*t.height/1254,r.width*t.width/1254,r.height*t.height/1254);var s=Sprite.Create(t,r,new Vector2(.5f,.13f),r.height/(i==0?3.1f:1.5f),0,SpriteMeshType.FullRect);ownedAssets.Add(s);var frames=new Sprite[16];for(int f=0;f<frames.Length;f++)frames[f]=s;enemyActionArt[kinds[i]]=frames;}var moldFrames=new Sprite[16];for(int f=0;f<16;f++)moldFrames[f]=WorkshopProp(1);enemyActionArt[EnemyKind.ForgeMold]=moldFrames;chapterFloors[1]=WorkshopProp(0);}
  private void AddFireWorkshop(){string[] names={"工坊门廊","铸模长廊","熔铸双径","煤仓内环","断链小庭","工匠避难间","风箱连廊","模具库","撤离桥头","链钩围场","铁砧前庭","守炉营地","锻链巨匠","降温炉台","地心炉门"};Array.Resize(ref chapterNames,30);for(int id=15;id<30;id++){int local=id-15,i=local-1;RoomKind kind=local==0||local==11||local>=13?RoomKind.Rest:local==12?RoomKind.Boss:local==3||local==10?RoomKind.Elite:local==7?RoomKind.Reward:local==5||local==8?RoomKind.Event:RoomKind.Combat;chapterNames[id]=names[local];journeyRooms.Add(new RoomNode{id=id,stage=1,floor=1,cell=local==0?new Vector2Int(-1,0):new Vector2Int(i%5,i/5),halfWidth=8.5f+local%2*.5f,halfHeight=4.9f,kind=kind,waves=kind==RoomKind.Elite?4:local%2==0?4:3,layout=id,depth=16,stairsTo=-1});}for(int a=15;a<30;a++)for(int b=a+1;b<30;b++)if((journeyRooms[a].cell-journeyRooms[b].cell).sqrMagnitude==1){journeyRooms[a].links.Add(b);journeyRooms[b].links.Add(a);}journeyRooms[14].stairsTo=15;journeyRooms[15].stairsTo=14;stageStarts[1]=15;stageEnds[1]=27;}
  private void MigrateFireCheckpoint(ChapterCheckpoint s){
   if(!fireChapterMode||s==null||s.island!="fire_coast"||s.rooms==null)return;
   int old=s.rooms.Length;if((old!=15||s.map!="fire-coast-v1")&&(old!=30||s.map!="fire-forge-v2"))return;
   var rooms=new ChapterRoomState[45];Array.Copy(s.rooms,rooms,old);for(int i=old;i<45;i++)rooms[i]=new ChapterRoomState{weapons=Array.Empty<CheckpointWeapon>(),crystals=Array.Empty<CheckpointEssence>()};
   s.rooms=rooms;s.map="fire-core-v3";s.fireHeart=s.fireHearth=false;s.fireEvac=0;s.ending=s.cgPending=false;
   if(old==15)s.forgeRescued=s.forgeBridge=s.emberRing=false;
  }
