  private void BuildWorkshopCover(RoomNode n){if(n.kind==RoomKind.Rest||n.kind==RoomKind.Event||n.kind==RoomKind.Reward||n.kind==RoomKind.Boss)return;Vector2[][] layouts={new[]{new Vector2(-4,2),new Vector2(4,-2)},new[]{new Vector2(-4,-2),new Vector2(4,2),new Vector2(0,2.7f)},new[]{new Vector2(-4,1.8f),new Vector2(4,1.8f),new Vector2(0,-2.4f)}};foreach(Vector2 at in layouts[n.layout%3]){if(IntersectsTransit(at,new Vector2(2.5f,2.4f)))continue;Sprite s=WorkshopProp(1);Draw("Forge anvil cover",s,at,Vector2.one,Color.white,DepthAt(at.y));AddRoundedCover(new Rect(at.x-.55f,at.y-.12f,1.1f,.38f),new Rect(at+(Vector2)s.bounds.min,(Vector2)s.bounds.size));}}
  private void SpawnWorkshopWave(RoomNode n){if(n.id==27){SpawnJourneyEnemy(EnemyKind.ForgeMaster,Vector2.zero,n.depth);foreach(Vector2 at in new[]{new Vector2(-3,1.8f),new Vector2(3,1.8f)}){var mold=SpawnJourneyEnemy(EnemyKind.ForgeMold,at,n.depth);mold.summoned=true;}return;}var rng=new System.Random(activeSeed+n.id*337+currentWave*79);int count=currentWave==1?4:5,cores=0,ranged=0;for(int i=0;i<count;i++){EnemyKind[] pool={EnemyKind.ForgeGuard,EnemyKind.MoltenCrab,EnemyKind.AshRaider,EnemyKind.AshBat,EnemyKind.CoalThrower,EnemyKind.FurnaceCore};EnemyKind k=pool[rng.Next(pool.Length)];if(k==EnemyKind.FurnaceCore&&cores++>=1)k=EnemyKind.ForgeGuard;if((k==EnemyKind.CoalThrower||k==EnemyKind.FurnaceCore)&&ranged++>=2)k=EnemyKind.AshBat;QueueEnemy(k,FindJourneySpawn(rng,.55f),n.kind==RoomKind.Elite&&i==0);pendingSpawns[pendingSpawns.Count-1].when=clock+1.3f+i*.35f;}}
  private void BuildWorkshopActions(RoomNode n){if(n.id==20){AddChapterAction(410,new Vector2(-3.8f,-.4f),forgeRescued?"与炉匠阿铎交谈":"转动绞盘 · 打开工匠避难间",WorkshopProp(2));var npcAt=forgeRescued?new Vector2(-.5f,.3f):new Vector2(-2,1.2f);var npc=Draw("Smith Ado",ResidentSprite(0),npcAt,Vector2.one,Color.white,DepthAt(npcAt.y));npc.transform.SetParent(chapterFocus.transform,true);IceCampWall(new Vector2(-3,1.35f),new Vector2(.12f,2));IceCampWall(new Vector2(-1,1.35f),new Vector2(.12f,2));IceCampWall(new Vector2(-2,2.3f),new Vector2(2,.12f));if(!forgeRescued){var gate=Draw("Workshop shelter gate",FireProp(3),new Vector2(-2,.4f),Vector2.one,Color.white,DepthAt(.4f));gate.transform.SetParent(chapterFocus.transform,true);IceCampWall(new Vector2(-2,.4f),new Vector2(2,.12f));}}
   if(n.id==23)BuildEvacuationCrossing(n);
   if(!n.cleared)return;if(n.id==15)AddChapterAction(412,new Vector2(-3,1),"查看阿铎留下的炉道图",lessonArtwork);if(n.id==28&&journeyRooms[27].cleared)AddChapterAction(413,new Vector2(-2,0),"沿撤离桥返回黑砂码头",FireProp(2));if(n.id==29)AddChapterAction(414,new Vector2(0,1),journeyRooms[27].cleared?"地心炉门 · 沿石阶进入第三层":"地心炉门 · 先平息锻链巨匠",FireProp(3));
